def even_odd_palindrome(n):
    count = [0, 0]
    for i in range(1, n + 1):
        s = str(i)
        if s == s[::-1]:
            if int(s) % 2 == 0:
                count[0] += 1
            else:
                count[1] += 1
    return tuple(count)
